 [('“Granted” (here) = ?',['admito, concedo','garantido','concedido por lei'],0,'Granted = concordo em parte.'),('“freeze” (here) = ?',['paralisar','congelar o alimento','resfriar'],0,'freeze = ficar paralisado.')],
