 [('I am ___ that your claim is sound. (convince)','convinced','crença.',None),('You have not ___ me to abandon my doubts. (persuade)','persuaded','ação.',None),('Please ___ evidence rather than rhetoric. (adduce)','adduce','registro acadêmico.',None),('She ___ me into signing. (talk)','talked','talk into.',None)],
 V('moral realism=realismo moral|mind-independent fact=fato independente da mente|motivational internalism=internalismo motivacional|error theory=teoria do erro|non-cognitivism=não cognitivismo|expressivism=expressivismo|supervenience=superveniência|moral objectivity=objetividade moral|normative claim=alegação normativa|descriptive claim=alegação descritiva|is-ought gap=lacuna entre ser e dever ser|open question argument=argumento da questão em aberto|draft essay=rascunho de ensaio|supervisor’s comment=comentário do orientador|margin gloss=glosa na margem|central claim=tese central|cogent case=caso consistente|valid inference=inferência válida|persuasive force=força persuasiva|rhetorical flourish=floreio retórico|evidential support=sustentação probatória|rival account=explicação rival|charitable reading=leitura caridosa|revised version=versão revisada|length cap=limite de extensão|submission deadline=prazo de entrega|extension request=pedido de prorrogação|colleague’s critique=crítica de colega|tone of collegial candour=tom de franqueza entre colegas'),
 ('Office hours',[('Mara','Have I convinced you that moral facts exist?','Eu convenci você de que fatos morais existem?'),('Hale','You have. But you have not persuaded me to drop my doubts.','Convenceu. Mas não me persuadiu a abandonar minhas dúvidas.'),('Mara','What would persuade you?','O que o persuadiria?'),('Hale','Evidence, not rhetoric.','Provas, não retórica.')]),
